$(document).ready(function(){if($("#_gestor-interface-edit-dados").length>0||$("#_gestor-interface-insert-dados").length>0){$(".targetDropdown").dropdown({onChange:function(e,n,t){if(e.length>0){var o=function(e,n,t){var o=new RegExp("([?&])"+n+"=.*?(&|$)","i"),r=-1!==e.indexOf("?")?"&":"?";return e.match(o)?e.replace(o,"$1"+n+"="+t+"$2"):e+r+n+"="+t}(window.location.href,"target",e);window.location.href=o}}})}});